export default "if (!HTMLCollection.prototype.forEach) HTMLCollection.prototype.forEach = Array.prototype.forEach;\n\n(() => {\r\n      const addFilterToolbar = (body, html, apply, reset) => {\r\n        const table = body?.closest('.excel-wrap');\r\n        if (!table || table.previousElementSibling?.dataset.tprmFilters) return;\r\n        const toolbar = document.createElement('div');\r\n        toolbar.className = 'toolbar';\r\n        toolbar.dataset.tprmFilters = 'true';\r\n        toolbar.innerHTML = html;\r\n        table.before(toolbar);\r\n        toolbar.querySelectorAll('input, select').forEach(control => control.addEventListener('input', apply));\r\n        toolbar.querySelectorAll('select').forEach(control => control.addEventListener('change', apply));\r\n        toolbar.querySelector('button').addEventListener('click', reset);\r\n        return toolbar;\r\n      };\r\n      const questionnaireToolbar = addFilterToolbar(document.querySelector('#questionnaireBody'), '<label class=\"search-box\"><span>/</span><input name=\"source-input-1\" type=\"search\" placeholder=\"Search vendor assessments...\" autocomplete=\"off\"></label><select name=\"source-select-2\"><option value=\"all\">All statuses</option><option>Draft</option><option>In progress</option><option>Complete</option><option>Expired</option><option>Final</option></select><select name=\"source-select-3\"><option value=\"all\">All results</option><option>Pending</option><option>Approved</option><option>Approved with Conditions</option><option>Rejected</option></select><button class=\"button button-quiet\" type=\"button\">Clear filters</button>', () => { questionnaireFilter.query = questionnaireToolbar.querySelector('input').value; questionnaireFilter.status = questionnaireToolbar.querySelectorAll('select')[0].value; questionnaireFilter.result = questionnaireToolbar.querySelectorAll('select')[1].value; renderQuestionnaires(); }, () => { questionnaireFilter = { query: '', status: 'all', result: 'all' }; questionnaireToolbar.querySelector('input').value = ''; questionnaireToolbar.querySelectorAll('select').forEach(select => { select.value = 'all'; }); renderQuestionnaires(); });\r\n      const tprmToolbar = addFilterToolbar(document.querySelector('#tprmBody'), '<label class=\"search-box\"><span>/</span><input name=\"source-input-4\" type=\"search\" placeholder=\"Search third-party risks...\" autocomplete=\"off\"></label><select name=\"source-select-5\"><option value=\"all\">All assessment statuses</option><option>Not started</option><option>Complete</option><option>Accepted</option></select><select name=\"source-select-6\"><option value=\"all\">All relationship statuses</option><option>Active</option><option>Offboarded</option><option>Expired</option><option>Terminated</option></select><select name=\"source-select-7\"><option value=\"all\">All CIA risk levels</option><option>High Risk (Tier 1)</option><option>Medium Risk (Tier 2)</option><option>Low Risk (Tier 3)</option></select><button class=\"button button-quiet\" type=\"button\">Clear filters</button>', () => { tprmFilter.query = tprmToolbar.querySelector('input').value; tprmFilter.status = tprmToolbar.querySelectorAll('select')[0].value; tprmFilter.relationshipStatus = tprmToolbar.querySelectorAll('select')[1].value; tprmFilter.riskLevel = tprmToolbar.querySelectorAll('select')[2].value; renderTprmRows(); }, () => { tprmFilter = { query: '', status: 'all', relationshipStatus: 'all', riskLevel: 'all' }; tprmToolbar.querySelector('input').value = ''; tprmToolbar.querySelectorAll('select').forEach(select => { select.value = 'all'; }); renderTprmRows(); });\r\n    })();\n"